// NewClientWithResponses creates a new ClientWithResponses, which wraps
// Client with return type handling
func NewClientWithResponses(server string, opts ...ClientOption) (*ClientWithResponses, error) {
	client, err := NewClient(server, opts...)
	if err != nil {
		return nil, err
	}
	return &ClientWithResponses{client}, nil
}

// WithBaseURL overrides the baseURL.
func WithBaseURL(baseURL string) ClientOption {
	return func(c *Client) error {
		newBaseURL, err := url.Parse(baseURL)
		if err != nil {
			return err
		}
		c.Server = newBaseURL.String()
		return nil
	}
}

// ClientWithResponsesInterface is the interface specification for the client with responses above.
type ClientWithResponsesInterface interface {

	// GetConfigWithResponse Get the running configuration
	//
	// The configuration as loaded (defaults applied). Secrets, once any exist, are never returned by this endpoint.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /config (the `GetConfig` operationId).
	GetConfigWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetConfigResponse, error)

	// PatchConfigWithBodyWithResponse Update configuration
	//
	// Validates and persists a partial configuration update to the config file. The capture pipeline is built at startup, so changes take effect after the appliance restarts; the response says whether a restart is pending.
	//
	// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with PATCH /config (the `PatchConfig` operationId).
	PatchConfigWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*PatchConfigResponse, error)

	// PatchConfigWithResponse Update configuration
	//
	// Validates and persists a partial configuration update to the config file. The capture pipeline is built at startup, so changes take effect after the appliance restarts; the response says whether a restart is pending.
	//
	// Takes a body of the `application/json` content type, and returns a wrapper object for the known response body format(s).
	//
	// Corresponds with PATCH /config (the `PatchConfig` operationId).
	PatchConfigWithResponse(ctx context.Context, body PatchConfigJSONRequestBody, reqEditors ...RequestEditorFn) (*PatchConfigResponse, error)

	// ListDevicesWithResponse List capture devices
	//
	// Every configured device with its configured and negotiated parameters and runtime state, including devices that failed to open (state "skipped") or died after startup (state "failed").
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /devices (the `ListDevices` operationId).
	ListDevicesWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ListDevicesResponse, error)

	// GetDeviceWithResponse Get one capture device
	//
	// The named device with its configuration and runtime state.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /devices/{name} (the `GetDevice` operationId).
	GetDeviceWithResponse(ctx context.Context, name string, reqEditors ...RequestEditorFn) (*GetDeviceResponse, error)

	// StreamEventsWithResponse Live event stream
	//
	// A single multiplexed Server-Sent Events stream for the whole
	// appliance. Each SSE event's `event:` field names its type and its
	// `data:` field is a JSON document:
	//
	// - `levels`: emitted at a fixed cadence (10 Hz) with one
	//   LevelsEvent covering every serving device. Peak and RMS are
	//   measured over the window since the previous event; meter
	//   ballistics (decay, peak hold) are the client's job.
	// - `heartbeat`: emitted every 15 seconds with `{}` as data, so
	//   idle connections stay alive and clients can detect a dead
	//   server. Sent as a named event (not an SSE comment) so simple
	//   fetch-based parsers see it.
	//
	// Further event types will be added additively; clients must ignore
	// event types they do not know. Level data is ephemeral: there is no
	// replay and `Last-Event-ID` is ignored.
	//
	// Browser note: the native EventSource API cannot send an
	// Authorization header, so an authenticated web client should
	// consume this endpoint with fetch and a streamed response body.
	//
	// OpenAPI 3.1 cannot type per-event payloads on a stream; the
	// `data:` schema for `levels` events is LevelsEvent. This operation
	// moves to OpenAPI 3.2 `itemSchema` once the code generators
	// support it.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /events (the `StreamEvents` operationId).
	StreamEventsWithResponse(ctx context.Context, params *StreamEventsParams, reqEditors ...RequestEditorFn) (*StreamEventsResponse, error)

	// GetHealthWithResponse Liveness probe
	//
	// Always available and unauthenticated. Reports only that the process is up; use /status for real state.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /healthz (the `GetHealth` operationId).
	GetHealthWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetHealthResponse, error)

	// GetStatusWithResponse Appliance status
	//
	// Appliance-level runtime state: version, uptime, RTSP listener, discovery, and per-device counts. Full per-device detail lives at /devices.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /status (the `GetStatus` operationId).
	GetStatusWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetStatusResponse, error)

	// GetSystemWithResponse Host system information
	//
	// Static hardware facts (platform, CPU, total memory and storage) and live host metrics (CPU and memory use, SoC temperature where a sensor exists), plus per-interface network details, for the web UI's host panel.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with GET /system (the `GetSystem` operationId).
	GetSystemWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*GetSystemResponse, error)

	// PostSystemRestartWithResponse Request an appliance restart
	//
	// Requests a graceful shutdown and restart of the appliance process. The server responds 202 Accepted, flushes in-flight responses, and initiates a graceful exit.
	//
	// Returns a wrapper object for the known response body format(s).
	//
	// Corresponds with POST /system/restart (the `PostSystemRestart` operationId).
	PostSystemRestartWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*PostSystemRestartResponse, error)
}

